package authorize

import (
	"context"
	"fmt"
	"net/url"

	"go.opentelemetry.io/contrib/instrumentation/google.golang.org/grpc/otelgrpc"
	oteltrace "go.opentelemetry.io/otel/trace"
	googlegrpc "google.golang.org/grpc"

	"github.com/pomerium/datasource/pkg/directory"
	"github.com/pomerium/pomerium/authorize/evaluator"
	"github.com/pomerium/pomerium/authorize/internal/store"
	"github.com/pomerium/pomerium/config"
	"github.com/pomerium/pomerium/internal/authenticateflow"
	"github.com/pomerium/pomerium/internal/log"
	"github.com/pomerium/pomerium/internal/mcp"
	"github.com/pomerium/pomerium/pkg/grpc"
	"github.com/pomerium/pomerium/pkg/grpc/databroker"
	"github.com/pomerium/pomerium/pkg/grpc/session"
	"github.com/pomerium/pomerium/pkg/grpc/user"
	"github.com/pomerium/pomerium/pkg/grpcutil"
	"github.com/pomerium/pomerium/pkg/storage"
)

type authenticateFlow interface {
	AuthenticateSignInURL(ctx context.Context, queryParams url.Values, redirectURL *url.URL, idpID string, additionalLoginHosts []string) (string, error)
}

type authorizeState struct {
	sharedKey                  []byte
	evaluator                  *evaluator.Evaluator
	dataBrokerClientConnection *googlegrpc.ClientConn
	dataBrokerClient           databroker.DataBrokerServiceClient
	sessionStore               *config.SessionStore
	idpTokenSessionCreator     config.IncomingIDPTokenSessionCreator
	idpResolver                *config.IdentityProviderResolver
	authenticateFlow           authenticateFlow
	syncQueriers               map[string]storage.Querier
	mcp                        *mcp.Handler
}

func newAuthorizeStateFromConfig(
	ctx context.Context,
	previousState *authorizeState,
	tracerProvider oteltrace.TracerProvider,
	cfg *config.Config,
	store *store.Store,
	outboundGrpcConn *grpc.CachedOutboundGRPClientConn,
	dataBrokerClient databroker.ClientGetter,
) (*authorizeState, error) {
	if err := validateOptions(cfg.Options); err != nil {
		return nil, fmt.Errorf("authorize: bad options: %w", err)
	}

	state := new(authorizeState)

	var err error
	var previousEvaluator *evaluator.Evaluator
	var previousIDPResolver *config.IdentityProviderResolver
	if previousState != nil {
		previousEvaluator = previousState.evaluator
		previousIDPResolver = previousState.idpResolver
	}

	state.sharedKey, err = cfg.Options.GetSharedKey()
	if err != nil {
		return nil, err
	}

	sharedKey, err := cfg.Options.GetSharedKey()
	if err != nil {
		return nil, err
	}

	cacheInvalidator := databroker.NewCacheInvalidator(storage.GlobalCache)
	cc, err := outboundGrpcConn.Get(
		ctx,
		&grpc.OutboundOptions{
			OutboundPort: cfg.OutboundPort,
			SignedJWTKey: sharedKey,
		},
		googlegrpc.WithStatsHandler(otelgrpc.NewClientHandler(otelgrpc.WithTracerProvider(tracerProvider))),
		googlegrpc.WithChainUnaryInterceptor(cacheInvalidator.UnaryClientInterceptor),
		googlegrpc.WithChainStreamInterceptor(cacheInvalidator.StreamClientInterceptor),
	)
	if err != nil {
		return nil, fmt.Errorf("authorize: error creating databroker connection: %w", err)
	}
	state.dataBrokerClientConnection = cc
	state.dataBrokerClient = databroker.NewDataBrokerServiceClient(cc)

	var evaluatorOptions []evaluator.Option
	if cfg.Options.IsRuntimeFlagSet(config.RuntimeFlagMCP) {
		mcp, err := mcp.New(ctx, mcp.DefaultPrefix, cfg, dataBrokerClient)
		if err != nil {
			return nil, fmt.Errorf("authorize: failed to create mcp handler: %w", err)
		}
		state.mcp = mcp
		evaluatorOptions = append(evaluatorOptions, evaluator.WithMCPAccessTokenProvider(mcp))
	}

	state.evaluator, err = newPolicyEvaluator(ctx, cfg.Options, store, previousEvaluator, evaluatorOptions...)
	if err != nil {
		return nil, fmt.Errorf("authorize: failed to update policy with options: %w", err)
	}

	state.sessionStore, err = config.NewSessionStore(cfg.Options)
	if err != nil {
		return nil, fmt.Errorf("authorize: invalid session store: %w", err)
	}
	// Built here, off the request path, reusing the previous generation's resolver
	// when nothing it is built from changed. It cannot fail: a provider that could
	// not be built rejects the tokens of its own issuer and reports itself
	// unhealthy, rather than failing this state build. That distinction matters
	// because OnConfigChange only logs a state-build error and keeps the previous
	// state, so failing here would silently discard every unrelated route and
	// policy change in this generation.
	state.idpResolver = config.NewIdentityProviderResolverFromConfig(ctx, cfg, previousIDPResolver)

	state.idpTokenSessionCreator = config.NewIncomingIDPTokenSessionCreator(
		tracerProvider,
		func(ctx context.Context, recordType, recordID string) (*databroker.Record, error) {
			return storage.GetDataBrokerRecord(ctx, recordType, recordID, 0)
		},
		func(ctx context.Context, records []*databroker.Record) error {
			res, err := state.dataBrokerClient.Put(ctx, &databroker.PutRequest{
				Records: records,
			})
			if err != nil {
				return err
			}
			storage.InvalidateCacheForDataBrokerRecords(ctx, res.Records...)
			return nil
		},
		config.WithIdentityProviderResolver(state.idpResolver),
	)

	if cfg.Options.UseStatelessAuthenticateFlow() {
		state.authenticateFlow, err = authenticateflow.NewStateless(ctx, tracerProvider, cfg, nil, nil, nil, nil, outboundGrpcConn)
	} else {
		state.authenticateFlow, err = authenticateflow.NewStateful(ctx, tracerProvider, cfg, nil, outboundGrpcConn)
	}
	if err != nil {
		return nil, err
	}

	state.syncQueriers = make(map[string]storage.Querier)
	if previousState != nil {
		if clientConnHasChanged(
			previousState.dataBrokerClientConnection,
			state.dataBrokerClientConnection,
		) {
			log.Ctx(ctx).Info().Msg("outbound client connection has changed")
			for recordType, v := range previousState.syncQueriers {
				log.Ctx(ctx).Info().Str("record-type", recordType).Msg("stopping sync querier")
				v.Stop()
			}
		} else {
			log.Ctx(ctx).Info().Msg("re-using previous sync queriers")
			state.syncQueriers = previousState.syncQueriers
		}
	}
	if cfg.Options.IsRuntimeFlagSet(config.RuntimeFlagAuthorizeUseSyncedData) {
		startSyncQueriersIfNotExist(ctx, state.dataBrokerClient, state.syncQueriers)
	}

	return state, nil
}

func clientConnHasChanged(previous, incoming *googlegrpc.ClientConn) bool {
	return previous != incoming
}

func startSyncQueriersIfNotExist(
	ctx context.Context,
	client databroker.DataBrokerServiceClient,
	syncQueriers map[string]storage.Querier,
) {
	log.Ctx(ctx).Debug().Int("num-queriers", len(syncQueriers)).Msg("refreshing sync queriers")
	for _, recordType := range []string{
		grpcutil.GetTypeURL(new(session.Session)),
		grpcutil.GetTypeURL(new(user.User)),
		grpcutil.GetTypeURL(new(user.ServiceAccount)),
		directory.GroupRecordType,
		directory.UserRecordType,
	} {
		if _, ok := syncQueriers[recordType]; !ok {
			log.Ctx(ctx).Debug().Str("record-type", recordType).Msg("registering new sync querier")
			syncQueriers[recordType] = storage.NewSyncQuerier(client, recordType)
		}
	}
	log.Ctx(ctx).Debug().Int("num-queriers", len(syncQueriers)).Msg("refreshed sync queriers")
}

// Package criteria contains all the pre-defined criteria as well as a registry to add new criteria.
package criteria

import (
	"sync"

	"github.com/open-policy-agent/opa/ast"

	"github.com/pomerium/pomerium/pkg/policy/generator"
)

// re-exported types
type (
	// A Generator generates a rego script from a policy.
	Generator = generator.Generator
	// A Criterion generates rego rules based on data.
	Criterion = generator.Criterion
	// A CriterionConstructor is a function which returns a Criterion for a Generator.
	CriterionConstructor = generator.CriterionConstructor
	// The CriterionDataType indicates the expected type of data for the criterion.
	CriterionDataType = generator.CriterionDataType
)

var allCriteria struct {
	sync.Mutex
	a []CriterionConstructor
}

// All returns all the known criterion constructors.
func All() []CriterionConstructor {
	allCriteria.Lock()
	a := allCriteria.a
	allCriteria.Unlock()
	return a
}

// Register registers a criterion.
func Register(criterionConstructor CriterionConstructor) {
	allCriteria.Lock()
	a := make([]CriterionConstructor, 0, len(allCriteria.a)+1)
	a = append(a, allCriteria.a...)
	a = append(a, criterionConstructor)
	allCriteria.a = a
	allCriteria.Unlock()
}

const (
	// CriterionDataTypeCertificateMatcher indicates the expected data type is
	// a certificate matcher.
	CriterionDataTypeCertificateMatcher CriterionDataType = "certificate_matcher"
	// CriterionDataTypeStringListMatcher indicates the expected data type is a string list matcher.
	CriterionDataTypeStringListMatcher CriterionDataType = "string_list_matcher"
	// CriterionDataTypeStringMatcher indicates the expected data type is a string matcher.
	CriterionDataTypeStringMatcher CriterionDataType = "string_matcher"
)

// NewCriterionRule generates a new rule for a criterion.
func NewCriterionRule(
	g *generator.Generator,
	name string,
	passReason, failReason Reason,
	body ast.Body,
) *ast.Rule {
	r1 := g.NewRule(name)
	r1.Head.Value = NewCriterionTerm(true, passReason)
	r1.Body = body

	r2 := &ast.Rule{
		Head: generator.NewHead("", NewCriterionTerm(false, failReason)),
		Body: ast.Body{
			ast.NewExpr(ast.BooleanTerm(true)),
		},
	}
	r1.Else = r2

	return r1
}

// NewCriterionDeviceRule generates a new rule for a criterion which
// requires a device and session. If there is no device "device-unauthenticated"
// is returned. If there is no session "user-unauthenticated" is returned.
func NewCriterionDeviceRule(
	g *generator.Generator,
	name string,
	passReason, failReason Reason,
	body ast.Body,
	deviceType string,
) *ast.Rule {
	r1 := g.NewRule(name)

	additionalData := map[string]any{
		"device_type": deviceType,
	}

	sharedBody := ast.Body{
		ast.Assign.Expr(ast.VarTerm("device_type_id"), ast.StringTerm(deviceType)),
		ast.MustParseExpr(`session := get_session(input.session.id)`),
		ast.MustParseExpr(`device_credential := get_device_credential(session, device_type_id)`),
		ast.MustParseExpr(`device_enrollment := get_device_enrollment(device_credential)`),
	}

	// case 1: rule passes, session exists, device exists
	r1.Head.Value = NewCriterionTermWithAdditionalData(true, passReason, additionalData)
	r1.Body = append(sharedBody, body...)

	// case 2: rule fails, session exists, device exists
	r2 := &ast.Rule{
		Head: generator.NewHead("", NewCriterionTermWithAdditionalData(false, failReason, additionalData)),
		Body: append(sharedBody, ast.Body{
			ast.MustParseExpr(`session.id != ""`),
			ast.MustParseExpr(`device_credential.id != ""`),
			ast.MustParseExpr(`device_enrollment.id != ""`),
		}...),
	}
	r1.Else = r2

	// case 3: device not authenticated, session exists, device does not exist
	r3 := &ast.Rule{
		Head: generator.NewHead("", NewCriterionTermWithAdditionalData(false, ReasonDeviceUnauthenticated, additionalData)),
		Body: append(sharedBody, ast.Body{
			ast.MustParseExpr(`session.id != ""`),
		}...),
	}
	r2.Else = r3

	// case 4: user not authenticated, session does not exist
	r4 := &ast.Rule{
		Head: generator.NewHead("", NewCriterionTermWithAdditionalData(false, ReasonUserUnauthenticated, additionalData)),
		Body: ast.Body{
			ast.NewExpr(ast.BooleanTerm(true)),
		},
	}
	r3.Else = r4

	return r1
}

// NewCriterionSessionRule generates a new rule for a criterion which
// requires a session. If there is no session "user-unauthenticated"
// is returned.
func NewCriterionSessionRule(
	g *generator.Generator,
	name string,
	passReason, failReason Reason,
	body ast.Body,
) *ast.Rule {
	r1 := g.NewRule(name)
	r1.Head.Value = NewCriterionTerm(true, passReason)
	r1.Body = body

	r2 := &ast.Rule{
		Head: generator.NewHead("", NewCriterionTerm(false, failReason)),
		Body: ast.Body{
			ast.MustParseExpr(`session := get_session(input.session.id)`),
			ast.MustParseExpr(`session.id != ""`),
		},
	}
	r1.Else = r2

	r3 := &ast.Rule{
		Head: generator.NewHead("", NewCriterionTerm(false, ReasonUserUnauthenticated)),
		Body: ast.Body{
			ast.NewExpr(ast.BooleanTerm(true)),
		},
	}
	r2.Else = r3

	return r1
}

