// Check implements the envoy auth server gRPC endpoint.
func (a *Authorize) Check(ctx context.Context, in *envoy_service_auth_v3.CheckRequest) (*envoy_service_auth_v3.CheckResponse, error) {
	ctx, span := a.tracer.Start(ctx, "authorize.grpc.Check")
	defer span.End()

	ctx = a.withQuerierForCheckRequest(ctx)

	state := a.state.Load()
	mcpEnabled := a.currentConfig.Load().Options.IsRuntimeFlagSet(config.RuntimeFlagMCP)

	// convert the incoming envoy-style http request into a go-style http request
	hreq := getHTTPRequestFromCheckRequest(in)
	requestID := requestid.FromHTTPHeader(hreq.Header)
	ctx = requestid.WithValue(ctx, requestID)

	req, err := a.getEvaluatorRequestFromCheckRequest(ctx, in)
	if errors.Is(err, errMCPRequestBodyTooLarge) || errors.Is(err, errMCPInvalidRequest) {
		return a.rejectMCPRequest(ctx, in, req, err)
	} else if err != nil {
		log.Ctx(ctx).Error().Err(err).Str("request-id", requestID).Msg("error building evaluator request")
		return nil, err
	}

	// Add MCP information to trace if available
	updateSpanWithMCPInfo(span, req.MCP)

	// Handle CORS preflight for MCP server routes.
	// OPTIONS requests must be answered with CORS headers before any auth
	// checks because browsers send preflight requests without credentials.
	if mcpEnabled && req.Policy.IsMCPServer() &&
		in.GetAttributes().GetRequest().GetHttp().GetMethod() == http.MethodOptions {
		headers := make(http.Header)
		mcp.SetCORSHeaders(headers)
		return mkDeniedCheckResponse(http.StatusNoContent, headers, ""), nil
	}

	// Cookie + Authorization: Bearer are mutually exclusive trust contexts,
	// but only on bearer_token_format: jwt routes: cookies come from a
	// browser, an external JWT comes from an M2M client, so a request
	// carrying both is a misconfigured client or a confusion attempt —
	// reject with 400. The IdP access/identity token formats predate this
	// check and allow both credentials together (a logged-in browser may
	// send its IdP token via Authorization; see TestBearerTokenFormat), and
	// on pass-through routes the Authorization header belongs to the
	// upstream, so neither may be rejected here.
	cfg := a.currentConfig.Load()
	req.BearerTokenFormat = cfg.GetBearerTokenFormatForPolicy(req.Policy)
	if req.BearerTokenFormat == configpb.BearerTokenFormat_BEARER_TOKEN_FORMAT_JWT &&
		hasCookieAndBearer(hreq, cfg.Options.CookieName) {
		log.Ctx(ctx).Info().
			Str("request-id", requestID).
			Msg("request carried both a session cookie and an Authorization: Bearer header on a bearer_token_format:jwt route; rejecting as 400")
		return a.deniedResponse(ctx, in, int32(http.StatusBadRequest), http.StatusText(http.StatusBadRequest), nil)
	}

	// load the session
	s, err := a.loadSession(ctx, hreq, req)
	if errors.Is(err, sessions.ErrInvalidSession) {
		// ENG-2172: if this is an invalid session, don't evaluate policy, return forbidden
		return a.deniedResponse(ctx, in, int32(http.StatusForbidden), http.StatusText(http.StatusForbidden), nil)
	} else if err != nil {
		return nil, fmt.Errorf("error loading session: %w", err)
	}

	if s != nil {
		req.Session.ID = s.GetId()
		req.Session.UserID = s.GetUserId()
	}

	res, err := state.evaluator.Evaluate(ctx, req)
	if err != nil {
		log.Ctx(ctx).Error().Err(err).Str("request-id", requestID).Msg("error during OPA evaluation")
		return nil, err
	}

	// if show error details is enabled, attach the policy evaluation traces
	if req.Policy != nil && req.Policy.ShowErrorDetails {
		ctx = contextutil.WithPolicyEvaluationTraces(ctx, res.Traces)
	}

	resp, err := a.handleResult(ctx, in, req, res)
	if err != nil {
		log.Ctx(ctx).Error().Err(err).Str("request-id", requestID).Msg("grpc check ext_authz_error")
	}
	a.logAuthorizeCheck(ctx, zerolog.InfoLevel, req, res, s)
	return resp, err
}

func (a *Authorize) loadSession(
	ctx context.Context,
	hreq *http.Request,
	req *evaluator.Request,
) (s sessionOrServiceAccount, err error) {
	requestID := requestid.FromHTTPHeader(hreq.Header)

	s, err = a.maybeGetSessionFromRequest(ctx, hreq, req)
	if err == nil {
		return s, nil
	} else if !errors.Is(err, sessions.ErrNoSessionFound) {
		log.Ctx(ctx).Info().
			Str("request-id", requestID).
			Err(err).
			Msg("error creating session from incoming request")
		return nil, err
	}

	h, hErr := a.state.Load().sessionStore.ReadSessionHandleAndCheckIDP(hreq)
	if h == nil {
		log.Ctx(ctx).Debug().
			Str("request-id", requestID).
			AnErr("handle-error", hErr).
			Msg("no session handle from request")
		return nil, nil
	}

	log.Ctx(ctx).Debug().
		Str("request-id", requestID).
		Str("handle-id", h.Id).
		Str("handle-idp-id", h.IdentityProviderId).
		Uint64("handle-record-version", h.GetDatabrokerRecordVersion()).
		Msg("decoded session handle from request")

	s, err = a.getDataBrokerSessionOrServiceAccount(ctx, h.Id, h.GetDatabrokerRecordVersion())
	if status.Code(err) == codes.Unavailable {
		log.Ctx(ctx).Debug().Str("request-id", requestID).Err(err).Msg("temporary error checking authorization: data broker unavailable")
		return nil, err
	} else if err != nil {
		log.Ctx(ctx).Info().Err(err).Str("request-id", requestID).Msg("clearing session due to missing or invalid session or service account")
		return nil, nil
	}

	return s, nil
}

var oidcBridgeEndpoints = []string{
	endpoints.PathOIDCAuth,
	endpoints.PathOIDCToken,
	endpoints.PathOIDCJWKS,
	endpoints.PathOIDCUserInfo,
}

func (a *Authorize) maybeGetSessionFromRequest(
	ctx context.Context,
	hreq *http.Request,
	req *evaluator.Request,
) (*session.Session, error) {
	policy := req.Policy
	if a.currentConfig.Load().Options.IsRuntimeFlagSet(config.RuntimeFlagMCP) {
		if policy.IsMCPServer() || strings.HasPrefix(hreq.URL.Path, mcp.DefaultPrefix) {
			s, err := a.getMCPSession(ctx, hreq)
			if err != nil {
				log.Ctx(ctx).Error().Err(err).Msg("error getting mcp session")
				return nil, err
			}
			return s, nil
		}
	}

	// this is a request sent to Pomerium's OIDC bridge endpoints
	if req.IsInternal && slices.Contains(oidcBridgeEndpoints, hreq.URL.Path) {
		// this sentinel allows Pomerium to continue through to its regular authorization flow
		// when Pomerium is configured with `bearer_token_format``: "idp_access_token", "idp_identity_token" or "jwt".
		//
		// Otherwise, bearer token formats conflict with OIDC bridge's functionality:
		//  1. OIDC Bridge mints tokens that are not associated with the idP, for use with its own
		//     OIDC provider endpoints
		//  2. bearer token handling below assumes that Authorization: Bearer <Token> is an idP
		//     token that must be verified upstream, which will result in a 403, instead of succeeding.
		return nil, sessions.ErrNoSessionFound
	}

	// attempt to create a session from an incoming idP token
	return a.state.Load().idpTokenSessionCreator.
		CreateSession(ctx, a.currentConfig.Load(), policy, hreq)
}

func (a *Authorize) getMCPSession(
	ctx context.Context,
	hreq *http.Request,
) (*session.Session, error) {
	auth := hreq.Header.Get(httputil.HeaderAuthorization)
	if auth == "" {
		return nil, fmt.Errorf("no authorization header was provided: %w", sessions.ErrNoSessionFound)
	}

	accessToken, ok := httputil.BearerToken(auth)
	if !ok {
		return nil, fmt.Errorf("authorization header does not use the Bearer scheme: %w", sessions.ErrNoSessionFound)
	}
	sessionID, sessionRecordVersion, err := a.state.Load().mcp.GetSessionAndVersionFromAccessToken(accessToken)
	if err != nil {
		return nil, fmt.Errorf("no session found for access token: %w: %w", err, sessions.ErrNoSessionFound)
	}

	// Read the session with the record version captured when the token was
	// issued. This gives read-your-writes: if the synced-data cache is behind
	// that version (e.g. a session just written on another databroker node), the
	// querier falls through to an authoritative databroker read instead of
	// reporting the session as missing and denying with a 401.
	record, err := storage.GetDataBrokerRecord(ctx, grpcutil.GetTypeURL(new(session.Session)), sessionID, sessionRecordVersion)
	if storage.IsNotFound(err) {
		return nil, fmt.Errorf("session databroker record not found: %w", sessions.ErrNoSessionFound)
	}

	msg, err := record.GetData().UnmarshalNew()
	if err != nil {
		return nil, fmt.Errorf("error unmarshalling session: %w: %w", err, sessions.ErrNoSessionFound)
	}

	s, ok := msg.(*session.Session)
	if !ok {
		return nil, fmt.Errorf("unexpected session type: %T: %w", msg, sessions.ErrNoSessionFound)
	}

	return s, nil
}

var (
	// errMCPRequestBodyTooLarge indicates that an MCP request body exceeds the
	// route's max_request_bytes.
	errMCPRequestBodyTooLarge = errors.New("MCP request body too large")
	// errMCPInvalidRequest indicates an MCP request that authorization cannot
	// be evaluated against.
	errMCPInvalidRequest = errors.New("invalid MCP request")
)

// rejectMCPRequest denies an MCP request that authorization cannot be
// evaluated against: 413 for an oversized body, 400 otherwise. The client has
// not been authenticated, so it is told the cause only if the route shows error
// details; the cause is always logged with the authorize check.
func (a *Authorize) rejectMCPRequest(
	ctx context.Context,
	in *envoy_service_auth_v3.CheckRequest,
	req *evaluator.Request,
	err error,
) (*envoy_service_auth_v3.CheckResponse, error) {
	code := http.StatusBadRequest
	if errors.Is(err, errMCPRequestBodyTooLarge) {
		code = http.StatusRequestEntityTooLarge
	}
	reason := http.StatusText(code)
	if req.Policy.ShowErrorDetails {
		reason = err.Error()
	}

	ctx = log.WithContext(ctx, func(c zerolog.Context) zerolog.Context { return c.Err(err) })
	a.logAuthorizeCheck(ctx, zerolog.InfoLevel, req, nil, nil)

	headers := make(http.Header)
	mcp.SetCORSHeaders(headers)
	return a.deniedResponse(ctx, in, int32(code), reason, headers)
}

// getEvaluatorRequestFromCheckRequest returns the evaluator request for a check
// request. For an MCP request that authorization cannot be evaluated against,
// it returns the request along with an errMCPRequestBodyTooLarge or
// errMCPInvalidRequest error.
//
// The body of a request to an MCP server route is inspected whether or not the
// mcp runtime flag is set: Envoy buffers and forwards it for such routes
// regardless of the flag, so skipping inspection would let mcp_tool rules in
// the route's policy fail open.
func (a *Authorize) getEvaluatorRequestFromCheckRequest(
	ctx context.Context,
	in *envoy_service_auth_v3.CheckRequest,

	defer span.End()
	span.SetAttributes(attribute.String("script_checksum", query.checksum()))

	rs, err := safeEval(ctx, query.PreparedEvalQuery,
		rego.EvalInput(req),
		rego.EvalPrintHook(regoPrintHook{
			logger: *log.Logger(),
		}))
	if err != nil {
		return nil, fmt.Errorf("authorize: error evaluating policy.rego: %w", err)
	}

	if len(rs) == 0 {
		return nil, fmt.Errorf("authorize: unexpected empty result from evaluating policy.rego")
	}

	res := &PolicyResponse{
		Allow: getRuleResult("allow", rs[0].Bindings),
		Deny:  getRuleResult("deny", rs[0].Bindings),
	}
	return res, nil
}

// getRuleResult gets the rule result var. It expects a boolean, [boolean, []string] or [boolean, []string, object].
func getRuleResult(name string, vars rego.Vars) (result RuleResult) {
	result = NewRuleResult(false)

	m, ok := vars["result"].(map[string]any)
	if !ok {
		return result
	}

	switch t := m[name].(type) {
	case bool:
		result.Value = t
	case []any:
		switch len(t) {
		case 3:
			v, ok := t[2].(map[string]any)
			if ok {
				maps.Copy(result.AdditionalData, v)
			}
			fallthrough
		case 2:
			// fill in the reasons
			v, ok := t[1].([]any)
			if ok {
				for _, vv := range v {
					result.Reasons.Add(criteria.Reason(fmt.Sprint(vv)))
				}
			}
			fallthrough
		case 1:
			// fill in the value
			v, ok := t[0].(bool)
			if !ok {
				return result
			}
			result.Value = v
		}
	}

	return result
}

type routeEvaluator struct {
	id        string
	evaluator *PolicyEvaluator
}

func getOrCreatePolicyEvaluators(
	ctx context.Context, cfg *evaluatorConfig, store *store.Store,
	cachedPolicyEvaluators map[string]*PolicyEvaluator,
) (map[string]*PolicyEvaluator, error) {
	now := time.Now()

	var reusedCount int
	m := make(map[string]*PolicyEvaluator)
	var builders []errgrouputil.BuilderFunc[routeEvaluator]
	for i := range cfg.Policies {
		configPolicy := cfg.Policies[i]
		id, err := configPolicy.RouteID()
		if err != nil {
			return nil, fmt.Errorf("authorize: error computing policy route id: %w", err)
		}
		p := cachedPolicyEvaluators[id]
		if p != nil && p.policyChecksum == configPolicy.Checksum() {
			m[id] = p
			reusedCount++
			continue
		}
		builders = append(builders, func(ctx context.Context) (*routeEvaluator, error) {
			evaluator, err := NewPolicyEvaluator(ctx, store, configPolicy, cfg.AddDefaultClientCertificateRule)
			if err != nil {
				return nil, fmt.Errorf("authorize: error building evaluator for route id=%s: %w", configPolicy.ID, err)
			}
			return &routeEvaluator{
				id:        id,
				evaluator: evaluator,
			}, nil
		})
	}

	evals, errs := errgrouputil.Build(ctx, builders...)
	if len(errs) > 0 {
		for _, err := range errs {
			log.Ctx(ctx).Error().Msg(err.Error())
		}
		return nil, fmt.Errorf("authorize: error building policy evaluators")
	}

	for _, p := range evals {
		m[p.id] = p.evaluator
	}

	log.Ctx(ctx).Debug().
		Dur("duration", time.Since(now)).
		Int("reused-policies", reusedCount).
		Int("created-policies", len(cfg.Policies)-reusedCount).
		Msg("updated policy evaluators")
	return m, nil
}

// Evaluate evaluates the rego for the given policy and generates the identity headers.
func (e *Evaluator) Evaluate(ctx context.Context, req *Request) (*Result, error) {
	ctx, span := trace.Continue(ctx, "authorize.Evaluator.Evaluate")
	defer span.End()

	start := time.Now()

	eg, ctx := errgroup.WithContext(ctx)

	var policyOutput *PolicyResponse
	eg.Go(func() error {
		var err error
		if req.IsInternal {
			policyOutput, err = e.evaluateInternal(ctx, req)
		} else {
			policyOutput, err = e.evaluatePolicy(ctx, req)
		}
		return err
	})

	var headersOutput *HeadersResponse
	eg.Go(func() error {
		var err error
		headersOutput, err = e.evaluateHeaders(ctx, req)
		return err
	})

	err := eg.Wait()
	if err != nil {
		return nil, err
	}

	e.evaluationCount.Add(ctx, 1)
	if policyOutput.Deny.Value {
		e.denyCount.Add(ctx, 1)
	} else if policyOutput.Allow.Value {
		e.allowCount.Add(ctx, 1)
	}
	e.evaluationDuration.Record(ctx, time.Since(start).Milliseconds())

	res := &Result{
		Allow:               policyOutput.Allow,
		Deny:                policyOutput.Deny,
		Headers:             headersOutput.Headers,
		HeadersToRemove:     headersOutput.HeadersToRemove,
		Traces:              policyOutput.Traces,
		AdditionalLogFields: headersOutput.AdditionalLogFields,
	}
	return res, nil
}

// Internal endpoints that require a logged-in user.
var internalPathsNeedingLogin = set.From([]string{
	endpoints.PathPomeriumJWT,
	endpoints.PathPomeriumUser,
	endpoints.PathPomeriumWebAuthn,
	endpoints.PathPomeriumRoutes,
	endpoints.PathPomeriumAPIRoutes,
	endpoints.PathPomeriumMCPAuthorize,
	endpoints.PathPomeriumMCPConnect,
	endpoints.PathPomeriumMCPRoutes,
})

func (e *Evaluator) evaluateInternal(_ context.Context, req *Request) (*PolicyResponse, error) {
	if internalPathsNeedingLogin.Contains(req.HTTP.Path) {
		if req.Session.ID == "" {
			return &PolicyResponse{
				Allow: NewRuleResult(false, criteria.ReasonUserUnauthenticated),
			}, nil
		}
	}

	return &PolicyResponse{
		Allow: NewRuleResult(true, criteria.ReasonPomeriumRoute),
	}, nil
}

func (e *Evaluator) evaluatePolicy(ctx context.Context, req *Request) (*PolicyResponse, error) {
	if req.Policy == nil {
		return &PolicyResponse{
			Deny: NewRuleResult(true, criteria.ReasonRouteNotFound),
		}, nil
	}

	id, err := req.Policy.RouteID()
	if err != nil {
		return nil, fmt.Errorf("authorize: error computing policy route id: %w", err)
	}

	policyEvaluator, ok := e.policyEvaluators[id]
	if !ok {
		return &PolicyResponse{
			Deny: NewRuleResult(true, criteria.ReasonRouteNotFound),
		}, nil
	}

	clientCA, err := e.getClientCA(req.Policy)
	if err != nil {
		return nil, err
	}

	isValidClientCertificate, err := isValidClientCertificate(
		clientCA, string(e.clientCRL), req.HTTP.ClientCertificate, e.clientCertConstraints)
	if err != nil {
		return nil, fmt.Errorf("authorize: error validating client certificate: %w", err)
	}

	return policyEvaluator.Evaluate(ctx, &PolicyRequest{
		HTTP:                     req.HTTP,
		SSH:                      req.SSH,
		MCP:                      req.MCP,
		Session:                  req.Session,
		IsValidClientCertificate: isValidClientCertificate,
	})
}

func (e *Evaluator) evaluateHeaders(ctx context.Context, req *Request) (*HeadersResponse, error) {
	res, err := e.headersEvaluators.Evaluate(ctx, req)
	if err != nil {
		return nil, err
	}

	carryOverJWTAssertion(res.Headers, req.HTTP.Headers)

	return res, nil
}

func (e *Evaluator) getClientCA(policy *config.Policy) (string, error) {
	if policy != nil && policy.TLSDownstreamClientCA != "" {
		bs, err := base64.StdEncoding.DecodeString(policy.TLSDownstreamClientCA)
		if err != nil {
			return "", err
		}
		return string(bs), nil
	}

	return string(e.clientCA), nil
}

func updateStore(store *store.Store, cfg *evaluatorConfig) error {
	jwk, err := getJWK(cfg)
	if err != nil {
		return fmt.Errorf("authorize: couldn't create signer: %w", err)
	}

	store.UpdateGoogleCloudServerlessAuthenticationServiceAccount(
		cfg.GoogleCloudServerlessAuthenticationServiceAccount,
	)
	store.UpdateJWTClaimHeaders(cfg.JWTClaimsHeaders)
	store.UpdateJWTGroupsFilter(cfg.JWTGroupsFilter)
	store.UpdateDefaultJWTIssuerFormat(cfg.DefaultJWTIssuerFormat)
	store.UpdateRoutePolicies(cfg.Policies)
	store.UpdateSigningKey(jwk)
	store.UpdateMCPAccessTokenProvider(cfg.MCPAccessTokenProvider)

	return nil
}

func getJWK(cfg *evaluatorConfig) (*jose.JSONWebKey, error) {
	var decodedCert []byte
	// if we don't have a signing key, generate one
	if len(cfg.SigningKey) == 0 {
		key, err := cryptutil.NewSigningKey()
		if err != nil {
			return nil, fmt.Errorf("couldn't generate signing key: %w", err)
		}
		decodedCert, err = cryptutil.EncodePrivateKey(key)
		if err != nil {
			return nil, fmt.Errorf("bad signing key: %w", err)
		}
	} else {
		decodedCert = cfg.SigningKey
	}

	jwk, err := cryptutil.PrivateJWKFromBytes(decodedCert)
	if err != nil {
		return nil, fmt.Errorf("couldn't generate signing key: %w", err)
	}

	return jwk, nil
}

func safeEval(ctx context.Context, q rego.PreparedEvalQuery, options ...rego.EvalOption) (resultSet rego.ResultSet, err error) {
	defer func() {
		if e := recover(); e != nil {
			err = fmt.Errorf("%v", e)
		}
	}()
	resultSet, err = q.Eval(ctx, options...)
	return resultSet, err
}

// carryOverJWTAssertion copies assertion JWT from request to response
// note that src keys are expected to be http.CanonicalHeaderKey
func carryOverJWTAssertion(dst http.Header, src map[string]string) {
	jwtForKey := httputil.CanonicalHeaderKey(httputil.HeaderPomeriumJWTAssertionFor)
	jwtFor, ok := src[jwtForKey]
	if ok && jwtFor != "" {
		dst.Add(jwtForKey, jwtFor)
		return
	}
	jwtFor, ok = src[httputil.CanonicalHeaderKey(httputil.HeaderPomeriumJWTAssertion)]
	if ok && jwtFor != "" {
		dst.Add(jwtForKey, jwtFor)
	}
}

