// getRuleResult gets the rule result var. It expects a boolean, [boolean, []string] or [boolean, []string, object].
func getRuleResult(name string, vars rego.Vars) (result RuleResult) {
	result = NewRuleResult(false)

	m, ok := vars["result"].(map[string]any)
	if !ok {
		return result
	}

	switch t := m[name].(type) {
	case bool:
		result.Value = t
	case []any:
		switch len(t) {
		case 3:
			v, ok := t[2].(map[string]any)
			if ok {
				maps.Copy(result.AdditionalData, v)
			}
			fallthrough
		case 2:
			// fill in the reasons
			v, ok := t[1].([]any)
			if ok {
				for _, vv := range v {
					result.Reasons.Add(criteria.Reason(fmt.Sprint(vv)))
				}
			}
			fallthrough
		case 1:
			// fill in the value
			v, ok := t[0].(bool)
			if !ok {
				return result
			}
			result.Value = v
		}
	}

	return result
}

