+		credential, err := v.getCredential(ctx, credentialID)
+		if err != nil {
+			lastErr = fmt.Errorf("%w: credential %q: %v", ErrDeviceUnauthenticated, credentialID, err)
+			continue
+		}
+		if credential.GetUserId() != "" && credential.GetUserId() != s.GetUserId() {
+			lastErr = fmt.Errorf("%w: credential %q belongs to another user", ErrDeviceUnauthorized, credentialID)
+			continue
+		}
+		if requirement.TypeID != "" && credential.GetTypeId() != requirement.TypeID {
+			lastErr = fmt.Errorf("%w: credential %q has type %q, expected %q",
+				ErrDeviceUnauthorized, credentialID, credential.GetTypeId(), requirement.TypeID)
+			continue
+		}
+
+		enrollment, err := v.getEnrollment(ctx, credential.GetEnrollmentId())
+		if err != nil {
+			lastErr = fmt.Errorf("%w: enrollment for credential %q: %v",
+				ErrDeviceUnauthenticated, credentialID, err)
+			continue
+		}
+		if err := verifyEnrollment(s.GetUserId(), credential, enrollment, requirement.Approval); err != nil {
+			lastErr = err
+			continue
+		}
