+	if lastErr != nil {
+		return nil, lastErr
+	}
+	if candidateCount == 0 {
+		return nil, fmt.Errorf("%w: no matching credential in session", ErrDeviceUnauthenticated)
+	}
+	return nil, ErrDeviceUnauthenticated
