                requestOptions={webAuthnRequestOptions}
                url={webAuthnUrl}
                size="small"
              />
            </Stack>
          </Toolbar>
          <Box sx={{ padding: 3, paddingTop: 0 }}>
            <DeviceCredentialsTable
