  1	// Package zerotrust compiles device and user access requirements from
  2	// Pomerium Policy Language and provides helpers for enforcing those
  3	// requirements at runtime.
  4	package zerotrust
  5	
  6	import (
  7		"fmt"
  8		"io"
  9		"slices"
 10	
 11		"github.com/pomerium/pomerium/pkg/policy"
 12		"github.com/pomerium/pomerium/pkg/policy/parser"
 13		"github.com/pomerium/pomerium/pkg/webauthnutil"
 14	)
 15	
 16	// PolicyCriterion is a criterion that contributed to a compiled policy.
 17	type PolicyCriterion struct {
 18		Action    parser.Action
 19		Operator  string
 20		Criterion parser.Criterion
 21	}
 22	
 23	// UserRequirements summarizes positive user identity checks in a policy.
 24	//
 25	// The generated Rego remains the source of truth for evaluation. These fields
 26	// are useful for auditing a policy and for rejecting configurations that do
 27	// not include an expected user check. Required only means a user check is
 28	// referenced by an allow rule; its and/or/not structure is preserved in Rego.
 29	type UserRequirements struct {
 30		Required         bool
 31		AnyAuthenticated bool
 32		UserIDs          []string
 33		Emails           []string
 34		Domains          []string
 35		Groups           []string
 36	}
 37	
 38	// DeviceRequirements summarizes positive device checks in a policy.
 39	//
 40	// Required only means a device check is referenced by an allow rule; its
 41	// and/or/not structure is preserved in Rego.
 42	type DeviceRequirements struct {
 43		Required         bool
 44		TypeIDs          []string
 45		CredentialIDs    []string
 46		RequiresApproval bool
 47		ForbidsApproval  bool
 48	}
 49	
 50	// CompiledPolicy is a Pomerium access policy with its generated Rego and a
 51	// normalized summary of the user and device constraints.
 52	type CompiledPolicy struct {
 53		Rego               string
 54		Criteria           []PolicyCriterion
 55		UserRequirements   UserRequirements
 56		DeviceRequirements DeviceRequirements
 57	}
 58	
 59	// Compile compiles a Pomerium Policy Language policy into Rego and extracts
 60	// user and device requirements from its allow rules.
 61	func Compile(p *parser.Policy) (*CompiledPolicy, error) {
 62		if p == nil {
 63			return nil, fmt.Errorf("zero trust: policy is nil")
 64		}
 65	
 66		rego, err := policy.GenerateRegoFromPolicy(p)
 67		if err != nil {
 68			return nil, fmt.Errorf("zero trust: compile policy: %w", err)
 69		}
 70	
 71		compiled := &CompiledPolicy{Rego: rego}
 72		users := newStringSet()
 73		emails := newStringSet()
 74		domains := newStringSet()
 75		groups := newStringSet()
 76		deviceTypes := newStringSet()
 77		deviceCredentials := newStringSet()
 78	
 79		for _, rule := range p.Rules {
 80			for _, group := range []struct {
 81				operator string
 82				criteria []parser.Criterion
 83			}{
 84				{operator: "and", criteria: rule.And},
 85				{operator: "or", criteria: rule.Or},
 86				{operator: "not", criteria: rule.Not},
 87				{operator: "nor", criteria: rule.Nor},
 88			} {
 89				for _, criterion := range group.criteria {
 90					compiled.Criteria = append(compiled.Criteria, PolicyCriterion{
 91						Action:    rule.Action,
 92						Operator:  group.operator,
 93						Criterion: criterion,
 94					})
 95	
 96					// Negative operators and deny rules are not positive
 97					// requirements. They are still preserved in Criteria above
 98					// and enforced by the generated Rego.
 99					if rule.Action != parser.ActionAllow ||
100						group.operator == "not" ||
101						group.operator == "nor" {
102						continue
103					}
104	
105					switch criterion.Name {
106					case "authenticated_user":
107						compiled.UserRequirements.Required = true
108						compiled.UserRequirements.AnyAuthenticated = true
109					case "user":
110						compiled.UserRequirements.Required = true
111						users.addAll(stringMatcherValues(criterion.Data))
112					case "email":
113						compiled.UserRequirements.Required = true
114						emails.addAll(stringMatcherValues(criterion.Data))
115					case "domain":
116						compiled.UserRequirements.Required = true
117						domains.addAll(stringMatcherValues(criterion.Data))
